      ellipse(0, 0, 25.3, 25.3, C.white, C.lacquer, 2.2);
      ellipse(0, 0, 20.8, 20.8, C.lacquer, C.lightGold, 1.7);
      ellipse(0, 0, 16.4, 16.4, C.ink, C.gold, 1.5);
