      const pupilX = tilt * 2.7 + side * 1.2;
      ellipse(pupilX, 0.5 - leap * 1.6, 9.4, 10.5, '#0F1721');
      ellipse(pupilX - 3.5, -5.4, 4.6, 4.5, C.white);
      ellipse(pupilX + 4.0, 4.7, 1.8, 1.8, '#B0CBBF');
      ctx.restore();
